package com.mediconnect.clinicalnote.domain;
import java.time.Instant; import java.util.UUID; import org.springframework.data.annotation.*; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document;
@Document(collection="clinical_notes") public class ClinicalNoteDocument { @Id private String id; @Indexed private UUID appointmentId; @Indexed private UUID patientId; @Indexed private UUID doctorId; private String content; @CreatedDate private Instant createdAt; @CreatedBy private String createdBy; protected ClinicalNoteDocument(){} public ClinicalNoteDocument(UUID appointmentId,UUID patientId,UUID doctorId,String content){this.appointmentId=appointmentId;this.patientId=patientId;this.doctorId=doctorId;this.content=content;} public String getId(){return id;} public UUID getAppointmentId(){return appointmentId;} public UUID getPatientId(){return patientId;} public UUID getDoctorId(){return doctorId;} public String getContent(){return content;} public Instant getCreatedAt(){return createdAt;} public String getCreatedBy(){return createdBy;} }
